window.__saqPaperQuestions("2019-1-islhd",[{"number":1,"title":"","stemText":"An 84 year old woman presents to the ED after a coughing episode yesterday lead to spontaneous abdominal wall bruising. It has worsened overnight and this morning has been brought in by an ambulance after a syncopal episode at home. She is also complaining of significant left sided abdominal pain. Her main comorbidity is that she has atrial fibrillation and has had a “valve replacement” following rheumatic fever as a child. She is on metoprolol and warfarin. Her INR at her GP was 2.9 earlier in the week.\nHer vital signs are:\n\nT 35.1\nP 91\n\nBP 73/50\n\nRR 24\n\nSaO2 92% RA\nShe receives 2 unit of packed red blood cells and her blood pressure improves sufficiently to be taken for a CT abdomen/pelvis. A single axial slice is shown below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the findings on the CT image provided (3 marks) You are considering reversing the anticoagulation, regarding prosthetic valve thrombosis, name 2 factors (relating to the valve) that effect this risk of this upon reversal (2 marks)"},{"id":"b","label":"Part B","prompt":"What is the daily thrombosis risk? (1 mark)"},{"id":"c","label":"Part C","prompt":"You decide to fully reverse the patient’s warfarin, outline your approach (3 marks) The patient requires a massive transfusion, name 6 laboratory targets for massive transfusion (6 marks)"},{"id":"d","label":"Part D","prompt":"Excluding resuscitation and reversal, outline your management plan for this patient (4 marks)"}],"propPages":["asset:img05e1ae5ee9a317b568"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Extensive left sided abdominal wall haematoma </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Arterial blush – suggesting active bleeding </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Swirl sign – hypodensity – suggesting active bleeding </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No haemoperitoneum / pneumoperitoneum </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Likely &lt;1% </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Vitamin K 10mg IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Prothrombinex 50u/kg IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">+/- FFP 2u (may be part of massive transfusion) </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><em>Resuscitation: Covered </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia: Fentanyl IV aliquots 25-50mcg titrated to pain </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific: Intervention Radiology for Embolisation of Vessel </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Disposition: HDU / ICU for haemodynamic monitoring, transfusion targets etc </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"An 18 year old university student attends the ED for review of a red, tender scalp swelling. His general practitioner has commenced a course of oral flucloxacillin yesterday however there has been minimal improvement.","parts":[{"id":"a","label":"Part A","prompt":"Describe the findings on this photograph (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"Describe the management of this condition (2 marks)"}],"propPages":["asset:imgef9946042346f8ed29"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Swelling right occipital region </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Erythematous </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Loss of hair </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Kerion – fungal infection </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Supportive: Simple analgesia e.g. paracetamol 1g PO Q6H PRN </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific: 6-8 weeks ORAL antifungal (itraconazole, terbinafine, griseofulvin) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Oral or IV antibiotics incorrect, Incision &amp; drainage = 0/2 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"You are working in a rural emergency department without obstetric or paediatric coverage. A 24 year old lady presents with intermittent abdominal cramping. She is 29 weeks pregnant in her first pregnancy and is planning to relocate for the birth after 36 weeks. She has had no vaginal fluid loss\n• r bleeding and is feeling normal fetal movements.\nHer vital signs are:\n\nT 37.2\nP 64\n\nBP 109/72\n\nRR 22\n\nSaO2 99% RA","parts":[{"id":"a","label":"Part A","prompt":"Other than preterm labour, name one other obstetric condition that requires consideration (1 mark) Name one investigation that can exclude the diagnosis of preterm labour. Explain the principle of its use (2 marks)"},{"id":"b","label":"Part B","prompt":"A cardiotocograph is performed (above), please interpret and provide summary (6 marks)"},{"id":"c","label":"Part C","prompt":"Outline the management of preterm labour in this woman (4 marks)"}],"propPages":["asset:img680b77906e49340411"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Placental abruption (concealed) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Summary = normal CTG </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Baseline rate ~140bpm = normal </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Normal variability ~15bpm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Accelerations present </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No decelerations </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Contractions present 3 every 10min </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Tocolysis: Nifedipine oral 20mg q30min up to 60mg, then QID </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Betamethasone 11.4mg IM x2 24hrs apart </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">IV Antibiotics: Benzylpenicillin 1.2g stat </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Neuroprotection: MgSO4 4g over 30min, then 1g/hr infusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Disposition = Retrieval to obstetric / paediatric facility </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 60 year old man with a known history of alcoholic liver disease and cirrhosis presents with reduced level of consciousness, which began as confusion the day prior. He is afebrile and his vital signs are within normal limits.","parts":[{"id":"a","label":"Part A","prompt":"Name 4 stigmata of chronic liver disease on physical examination (2 marks)"},{"id":"b","label":"Part B","prompt":"Other than hepatic encephalopathy, name 4 relevant differential diagnoses in this patient? (4 marks)"},{"id":"c","label":"Part C","prompt":"Name 4 important precipitants of hepatic encephalopathy (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Palmar erythema </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Spider naevi </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Jaundice </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Ascites </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Splenomegaly </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Gynaecomastia </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Alcohol / other drug intoxication </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Head injury e.g. subdural haematoma </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Electrolyte disturbance e.g. hyponatraemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Endocrine cause e.g. hypoglycaemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Anything reasonable but must have 2/4 from above </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Alcohol ingestion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Upper GI bleeding </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Spontaneous bacterial peritonitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Portal vein thrombosis </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 24 year old woman in her first pregnancy comes to the emergency department with a small\namount of vaginal bleeding and lower abdominal cramping. She has no significant past medical history and has been taking folate supplementation since her positive urine pregnancy test 3 weeks ago.\nHer vital signs:\n\nT 36.5\nP77\n\nBP 102/67\n\nBlood tests show:\n\nHb 134\nA Negative\nBhCG 6,440\nShe has a transvaginal ultrasound Report states: “There is an intrauterine gestational sac which has a mean sac diameter of 26.2mm but no fetal pole is visualised. There is no evidence of extrauterine pregnancy and no free fluid”","parts":[{"id":"a","label":"Part A","prompt":"What is the diagnosis and viability of the pregnancy? (2 marks)"},{"id":"b","label":"Part B","prompt":"What are the 3 management options for this condition? (3 marks)"},{"id":"c","label":"Part C","prompt":"Regarding surgical management, name 2 absolute indications for its use (2 marks)"},{"id":"d","label":"Part D","prompt":"The patient requires Rh immunoglobulin, what is the dose and route of this medication? (1 mark)"}],"propPages":["asset:imgbabd7d7964066c0f91","asset:img1d45a33fb2b8f96783","asset:imgca419a47649a75480b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Non-viable </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Missed Miscarriage / Anembryonic pregnancy / Blighted ovum </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Expectant Mx </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Medical Mx – misoprostol 800mg PV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Surgical Mx – suction evacuation </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Severe bleeding / haemorrhagic shock </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Septic miscarriage </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">250iu IM </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 24 year old man with a history of bipolar affective disorder is brought to the emergency department by friends who are concerned he has been non-compliant with his lithium. His friends are concerned he has become manic.","parts":[{"id":"a","label":"Part A","prompt":"What are the clinical features of mania? (4 marks) The patient is admitted to the mental health ward and recommenced on lithium therapy. Your medical student has several questions regarding lithium toxicity."},{"id":"b","label":"Part B","prompt":"What are the main clinical features of a large acute lithium overdose (2 marks)"},{"id":"c","label":"Part C","prompt":"What are the main clinical features of a chronic lithium toxicity? (4 marks)"},{"id":"d","label":"Part D","prompt":"Name 3 factors predispose a patient to chronic lithium toxicity? (3 marks)"},{"id":"e","label":"Part E","prompt":"What is the modality and name 3 indications for enhanced elimination in lithium toxicity. (3 marks) Modality Indications"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Inflated self-esteem / grandiosity </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Decreased sleep </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">More talkative </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Flight of ideas </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Distractability </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Increased goal-directed activity  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Excessive involvement in pleasurable activities with high risk of bad outcome </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Mainly GI toxicity (heavy metal): &lt;25g mild-mod GI, &gt;25g mod-severe GI +/- neurotoxicity (rare) </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Mostly neurotoxicity / progressive based on symptoms </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Grade 1 = tremor, agitation, hyper-reflexia, ataxia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Grade 2 = stupor, rigidity, hypotension </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Grade 3 = coma, seizures, myoclonus </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Impaired renal function </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Diabetes insipidus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sodium depletion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Dehydration </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Drug interactions [NSAIDs / ACEi / thiazides] </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Modality</div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemodialysis </span></div><div class=\"answer-line\">Indications</div><div class=\"answer-line\"><span class=\"answer-source-red\">Established neurotoxicity </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Serum Li &gt; 2.5 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal impairment </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 72 year old woman is brought in by ambulance following a syncopal episode that she completely recovered from. She has recently been admitted for a syncope work up with no diagnosis found. En route to the emergency department she becomes unresponsive with low blood pressure.\nShe has a 12 lead ECG done in the resus room (see next page)\nHer vital signs are:\n\nBP 82 / 55\n\nRR 24\n\nSaO2 84% on RA\n\nT 36.4","parts":[{"id":"a","label":"Part A","prompt":"Describe the main ECG findings of importance (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark) What are 3 potentially reversible precipitants of this condition? Give examples where appropriate (3 marks)"},{"id":"c","label":"Part C","prompt":"Outline your management of this patient (5 marks)"}],"propPages":["asset:imgc9869cffa631d4c46b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Severe bradycardia, rate 20 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">AV dissociation / complete heart block </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Broad complex escape – likely ventricular </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Peaked T waves </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Complete heart block with ventricular escape  </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Seek and treat precipitant e.g. hyperkalaemia (calcium gluconate is reasonable empirically) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Medical Mx:  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Atropine is likely to fail, so poor answer </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Adrenaline 25-50mcg IV bolus’ at bedside is reasonable </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Isoprenaline / Adrenaline infusion with dose / rate is reasonable </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"> Electrical Mx: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Transcutaneous Pacing with reasonable description / analgesia is reasonable </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Disposition: Referral to Cardiology for Emergent Transvenous Pacemaker is essential </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 62 year old man with a history of multiple myeloma presents to the ED with severe pain to his left leg. On assessment he is clearly in pain, his vital signs are within normal limits and a photograph of his lower limbs is available below.","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"Name 2 investigations you could perform to confirm the diagnosis (2 marks). Give a justification for each."},{"id":"c","label":"Part C","prompt":"What are the management priorities in this case (4 marks)"}],"propPages":["asset:imgc3448e552f1f2dd3b6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Phlegmasia cerulea dolens  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Large DVT with potential for complete venous occlusion and infarction</span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>each.</td><td><span class=\"answer-source-red\">US lower limb: Non-compressible deep veins / no variance to pulse wave doppler of iliac veins / </span></td></tr><tr><td><span class=\"answer-source-red\">assess arterial flow </span></td><td><span class=\"answer-source-red\">CT venogram: Assess clot burden / degree of venous occlusion etc / anatomical mapping pre-</span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia – drug / dose / route required </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Anticoagulation – Heparin infusion preferred with loading / maintenance and target aPTT </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Emergent Vascular surgery referral for consideration of thrombectomy / catheter directed </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">thrombolysis </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 6 year old Indigenous girl is transferred to your hospital from a rural facility with a right lower lobe pneumonia that is not improving despite 4 days of intravenous benzylpenicillin. On day 4 of admission she has had a repeat chest X ray showing development of a parapneumonic effusion.\nHer vital signs are:\n\nT 39.2\nP 152\nCentral cap refill 2.5sec\n\nRR 42\n\nSaO2 93% on 3L/min via nasal prongs","parts":[{"id":"a","label":"Part A","prompt":"What are the biochemical features of a pleural effusion that suggest empyema? (3 marks) You perform a bedside lung ultrasound and in the right lower zone, you obtain the image below"},{"id":"b","label":"Part B","prompt":"Describe 2 important features of this ultrasound (2 marks)"},{"id":"c","label":"Part C","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"d","label":"Part D","prompt":"Outline the medical and surgical management for this condition (5 marks) END OF BOOKLET"}],"propPages":["asset:img26be249ac34805cb48"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Purulent pleural fluid </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">1 or more of following: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">+ gram stain / culture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">WCC &gt; 50,000 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pleural fluid glucose &lt;3 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pleural fluid pH &lt;7.2 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pleural fluid LDH &gt;1000 </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Effusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Loculated </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Consolidated lung </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Empyema</span><span class=\"answer-source-red\"><strong> </strong></span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Supportive:  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Supplemental O2  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Fluids/nutrition (considering SIADH / catabolism etc) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific (Medical):  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">IV Abs Broad Spectrum (Piperacillin-Tazobactam or Cefotaxime + Vancomycin if MRSA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">suspected) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Large Bore Chest drain (large size) ~20Fr </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific (Surgical Options): </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Fibrinolytics via chest drain </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">VATS – video-assisted thoracoscopic surgery  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Open thoracotomy </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 32 year old man is involved in an amateur mixed martial arts bout and is slammed onto the ground, complaining of immediate neck pain as well as being unable to move his hands or feet.\nHis vital signs are:\n\nT 35.8 P 48 BP 75/40 RR 24 SaO2 96% RA\nHe has clinical evidence of a spinal cord injury on examination A single image from his CT cervical spine is attached.","parts":[{"id":"a","label":"Part A","prompt":"Describe 2 abnormal findings on this CT scan (2 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"Name 5 unstable C spine fracture patterns (5 marks)"},{"id":"d","label":"Part D","prompt":"Compare the clinical features of spinal and neurogenic shock (4 marks) Spinal Shock Neurogenic Shock"},{"id":"e","label":"Part E","prompt":"Above what spinal level is neurogenic shock likely to occur? (1 mark)"},{"id":"f","label":"Part F","prompt":"Describe the supportive care (and targets) in neurogenic shock (3 marks)"}],"propPages":["asset:img831a471dccbc49321a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Anterolisthesis (anterior displacement) of C4 on C5 without obvious fracture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Narrowing of vertebral foramen at this site </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Bilateral facet joint dislocation </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Atlantoaxial dislocation or dissociation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Jeffersons # (Burst C1) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Hangmans # (Bilateral pedicle C2) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Type 2 or 3 Odontoid Process # </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Tear drop fracture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">PLUS: Bilateral facet joint dislocation </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Spinal shock = neurological injury to spinal cord / initial period of cord ‘confusion’ that may </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">overestimate degree of permanent neurological injury </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Neurogenic shock = distributive shock due to lack of sympathetic tone </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\"> Injury above T6 </span></div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Supportive care: Immobilisation of injury / Analgesia / Antiemetics </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Maintain MAP 85-90 with IV Fluid Hartmanns 1-2 L then noradrenaline infusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Maintain normoxia / normoglycaemia / normothermia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">IDC / pressure area care / VTE prophylaxis etc</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 35 year old man has a fall onto his out-stretched right hand after a fall down several steps. He has an isolated right wrist injury. The following Xrays are taken.","parts":[{"id":"a","label":"Part A","prompt":"Please outline the abnormalities on this Xray (4 marks) With the exception of neurovascular compromise, please outline 4 indications for closed reduction\n• f this fracture type/pattern, include with specific targets (4 marks)\nYou chose to perform a Biers block to facilitate closed reduction. Name 4 contraindications to performing this procedure (4 marks)"}],"propPages":["asset:img3e82358efd9d55bf79"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Extraarticular distal radius # </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">25% posterior displacement </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">45o dorsal angulation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Minimally displaced ulna styloid # </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"It has been noticed that a middle-aged male patient has been presenting to the emergency department several times per week with chest pain. He has a prior history of AMI requiring a stent but his most recent angiogram is normal and his disease is judged to be under control by his cardiologist. Each presentation his ECG is normal and his troponins are not elevated. So far there hasn’t been a concern regarding alternate pathology. You have been asked by the Director of Emergency Medicine to draft a management plan given his frequent presentations.","parts":[{"id":"a","label":"Part A","prompt":"Name 4 goals of an individualised care plan for a ‘frequent presenter’ (4 marks)\nWho are the likely key stakeholders in this instance (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">not to miss serious illness </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">help patient in the long term </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">improve patient care </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">minimise ED stay </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">improve engagement with community supports/services </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 4 year old boy is being managed in the paediatric bay as asthma. He presented with tachypnoea and has had a burst therapy of 3 doses of 6 puffs salbutamol with no improvement. Nursing staff have asked for you to review the patient as they have noticed the patient is very tachycardic. On review the child is mildly tachypnoeic, has normal central capillary refill and has a clear chest on auscultation. An ECG is performed and is below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the main features of this 12 lead ECG (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"Describe the escalating management options for this child (4 marks)"}],"propPages":["asset:img1cdc83a0900bd66109"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Tachycardia – rate ~260 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Narrow complex </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Regular R-R intervals </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No clear sinus P waves </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Supraventricular tachycardia </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Simple manoeuvres – e.g. ice pack on face </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Adenosine 100mcg/kg IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Repeat adenosine 200mcg/kg then 300mcg/kg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">(Verapamil IV is an option, not &lt;1yr, still controversial &lt;5yrs) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">DC cardioversion (under sedation): 1J/kg , then 2J/kg </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 32 year old man has been brought in by ambulance with altered level of consciousness after being seen to be well by family throughout the day. He has no past medical history and takes no regular medications.\nHis vital signs are:\n\nT 37.2\nP 126\n\nBP 110/72\n\nRR 30\n\nGCS 7 (E1V2M4)\n\nSaO2 100% on RA\nHe has a venous blood gas taken on arrival in the resus room\n\npH 7.09\n\npO2 32\n\npCO2 18\n\nHCO3 7\n\nNa 134\n\nK 6.2\n\nCl 98\ni Ca 1.02\n\nLactate 5.1\n\nGlucose 8.1\n\nCreatinine 67\n\nUrea 8.0\n\nHb 143\nOsm (meas) 307","parts":[{"id":"a","label":"Part A","prompt":"Please interpret this venous blood gas including all relevant calculations (8 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark) What 2 physiological factors may complicate this rapid sequence induction (RSI). For each, please"},{"id":"c","label":"Part C","prompt":"• utline a modification to the RSI process (4 marks)\nPhysiological Factor RSI Modification"},{"id":"d","label":"Part D","prompt":"What are the management priorities for this patient? (4 marks)"},{"id":"e","label":"Part E","prompt":"What are 4 indications for enhanced elimination in this patient (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Profound acidaemia pH 7.09 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Isolated raised anion gap metabolic acidosis (DDx lactaemia / ketoacidosis / toxic alcohol) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">HCO3 7 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Anion gap </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Delta ratio ~1 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Additional respiratory acidosis CO2 32 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Expected CO2 = 18 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Corrected K+ ~3.2 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Raised Osmolar gap = 23 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Oxygenation not assessible </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Toxic alcohol poisoning </span></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">pH 7.09</div><div class=\"answer-line\">pO2 32</div><div class=\"answer-line\">pCO2 18</div><div class=\"answer-line\">HCO3 7</div><div class=\"answer-line\">Na 134</div><div class=\"answer-line\">K 6.2</div><div class=\"answer-line\">Cl 98</div><div class=\"answer-line\">i Ca 1.02</div><div class=\"answer-line\">Lactate 5.1</div><div class=\"answer-line\">Glucose 8.1</div><div class=\"answer-line\">Creatinine 67</div><div class=\"answer-line\">Urea 8.0</div><div class=\"answer-line\">Hb 143</div><div class=\"answer-line\">Osm (meas) 307</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Secure airway / control ventilation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Support haemodynamics </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Ethanol  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">8mL/kg of 10% ethanol IV loading dose, then 1-2mL/kg/hr </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">4 x 30mL shots of vodka (~40% EtOH), then ~1 shot per hour) via NG or OG </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemodialysis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Critical care unit / Consideration of suicidality </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Haemodialysis is EE modality of choice </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Indications: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Large ingestion with Osmolar gap &gt;10 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">pH &lt;7.30 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal failure </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Deterioration in vital signs </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific level: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Methanol &gt; 16mmol/L </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Ethylene glycol &gt;8mmol/L </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 21 year old man is brought into the ED from a music festival complaining of shortness of breath and chest pain. His lips are cyanosed and vital signs are as follows:\n\nT 36.2\nP 121\n\nBP 130/88\n\nRR 34\n\nSaO2 85% (10L/min)","parts":[{"id":"a","label":"Part A","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"What is the pathogenesis of the patient’s symptoms? (2 marks)"},{"id":"c","label":"Part C","prompt":"Name 4 agents that can cause this condition (4 marks)"},{"id":"d","label":"Part D","prompt":"Outline your management of this patient (3 marks)"}],"propPages":["asset:imgd1742c01baad625682"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Methaemoglobinaemia </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Fe 2+ portion of haem is changed to Fe 3+ causing to haemoglobin to be converted to </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">methaemoglobin </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Reduced O2-carrying capacity and resultant hypoxia </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Exposure to oxidising agents: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Local anaesthetics: Prilocaine / Lignocaine </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Nitrites e.g. amyl nitrate </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Dapsone </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Antimalarials e.g. chloroquine </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Apply oxygen via non-rebreather mask (NRBM)  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Methylene blue 1mg/kg over 5min, repeat dose at 30-60min </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Remove precipitating agent / admit to HDU / seek &amp; treat complications and consider DDx </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 73 year old man is brought into the ED with left sided chest discomfort and is diagnosed with a NSTEMI on the basis of high lateral T wave inversion and a positive initial troponin T of 64 (reference range 0-14). The nurse notifies you that he wishes to self-discharge as his pain has resolved and he feels well.","parts":[{"id":"a","label":"Part A","prompt":"Outline some important medical risks of self-discharge in this scenario (3 marks)"},{"id":"b","label":"Part B","prompt":"Name 5 considerations when assessing a person’s capacity to make a decision (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Progression to STEMI </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">VT / VF – sudden cardiac death </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CCF </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Progression to STEMI </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">VT / VF – sudden cardiac death </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CCF </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"You are a new consultant working in an urban emergency department. The director approaches you and asks you to investigate the high proportion of ‘did not wait’ presentations. She is concerned these DNW figures represent","parts":[{"id":"a","label":"Part A","prompt":"What is the (generally accepted) maximum accepted percentage of patients who DNW? (1 mark)"},{"id":"b","label":"Part B","prompt":"Name two patient groups who are often over-represented within DNW statistics (2 marks)"},{"id":"c","label":"Part C","prompt":"Name 4 reasons for high DNW numbers and propose 4 solutions (4 marks)\nReason Solution"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">&lt;5% </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Children </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Mental health patients </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">High DNW is mainly caused by long-wait times which is generally due to ED overcrowding and access </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">block. Any reasonable reasons/solutions are ok. Examples below. </span></td></tr><tr><td>Reason</td><td>Solution</td></tr><tr><td><span class=\"answer-source-red\">WR not suitable for patients awaiting care </span></td><td><span class=\"answer-source-red\">Access to food / water / entertainment / nurse </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">in WR </span></td></tr><tr><td><span class=\"answer-source-red\">Long wait to fast-track / paed cases </span></td><td><span class=\"answer-source-red\">FT/paed stream / separate staff allocation </span></td></tr><tr><td><span class=\"answer-source-red\">Inadequate medical staffing </span></td><td><span class=\"answer-source-red\">Hire more staff </span></td></tr><tr><td><span class=\"answer-source-red\">Poor access to ED beds due to admissions </span></td><td><span class=\"answer-source-red\">Hospital-wide approach to access block – early </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">discharge, senior review etc </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"You are working as the consultant in a large metropolitan emergency department when you receive a pre-notification of a 16 day old child who is unresponsive, floppy with tachypnoea. They will arrive\nin 10min.","parts":[{"id":"a","label":"Part A","prompt":"Outline the key aspects of your preparation (4 marks) Regarding the differential diagnosis of a critically unwell neonate, name 5 major aetiologies with an example for each (5 marks) Name 3 clinical signs on examination that would make you suspect a duct-dependent cardiac lesion? (3 marks) What are the two main groups of duct-dependent cardiac lesions? Give 2 examples from each (4 marks) What medication can be used in the treatment of duct-dependent cardiac lesions? How is it"},{"id":"b","label":"Part B","prompt":"administered and name one adverse effect? (2 marks) END OF BOOKLET"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Staff </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">ED staff: roles </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Inpatient staff: notification / roles </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Space </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Resus bay </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Stuff: Equipment / Drugs </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Airway / vascular access equipment </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Antibiotics / Dextrose / Fluid / Adrenaline doses </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Strategy </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Debrief staff expected patient issues / priorities / direction of care </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Offload responsibility to rest of department / notify RN in charge </span></td><td></td></tr><tr><td>Regarding the differential diagnosis of a critically unwell neonate, name 5 major aetiologies with an</td><td></td></tr><tr><td>example for each (5 marks)</td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Sepsis </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">congenital heart disease </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">metabolic disturbance </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">electrolyte abnormality – often Na+  </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">endocrine disturbance </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">adrenal insufficiency </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">hypoglycaemia </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">non-accidental injury </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Others: </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Overdose/tox </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Seizures </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">GI emergencies </span></td><td></td></tr><tr><td>ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</td><td></td></tr><tr><td>Name 3 clinical signs on examination that would make you suspect a duct-dependent cardiac lesion?</td><td></td></tr><tr><td>(3 marks)</td><td></td></tr><tr><td><span class=\"answer-source-red\">Cyanosis / Hypoxia </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Hyperoxia test: failing to increase SaO2 </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">No femoral pulses </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Hepatomegaly </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Murmur </span></td><td></td></tr><tr><td>What are the two main groups of duct-dependent cardiac lesions? Give 2 examples from each (4</td><td></td></tr><tr><td>marks)<span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Duct-dependent pulmonary circulation </span></td><td><span class=\"answer-source-red\">Duct-dependent systemic circulation </span></td></tr><tr><td><span class=\"answer-source-red\">Pulmonary atresia </span></td><td><span class=\"answer-source-red\">Coarctation of aorta </span></td></tr><tr><td><span class=\"answer-source-red\">Critical pulmonary stenosis </span></td><td><span class=\"answer-source-red\">Critical aortic stenosis </span></td></tr><tr><td><span class=\"answer-source-red\">Tricuspid atresia </span></td><td><span class=\"answer-source-red\">Hypoplastic left heart syndrome </span></td></tr><tr><td><span class=\"answer-source-red\">Present with hypoxia / cyanosis </span></td><td><span class=\"answer-source-red\">Present with shock / acidosis </span></td></tr><tr><td><span class=\"answer-source-red\">Note: Duct-dependent pulmonary AND systemic circulation = transposition of the great arteries </span></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Prostaglandin E1 (Prostin) Infusion: 50ng/kg/min, can increase to 100ng/kg/min </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Adverse effects: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Main one = apnoea </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Others: Hypotension, Hypoglycaemia, Transient hyperthermia and others </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</div><div class=\"answer-line\">Book 3</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"Your junior registrar is seeing a 46 year old woman with fevers and altered mental status who looks unwell. At this stage they haven’t been able to locate a source of infection and have empirically treated her with intravenous flucloxacillin and gentamicin. You review the patients full blood count (FBC), results below\n\nHb 108\n\nWCC 6.5\n\nPlatelets 43\nIn ideal circumstances, below what platelet level would you organise a platelet transfusion to facilitate (1.5 marks) Lumbar puncture (afebrile): < _____ Central venous catheter: < _____ Asymptomatic patient: < _____","parts":[{"id":"a","label":"Part A","prompt":"What are the 5 features of TTP? (2.5 marks)"},{"id":"b","label":"Part B","prompt":"Discuss the treatment options for TTP (3 marks) Complete the following table that compares the following serious causes of thrombocytopaenia (6 marks) TTP DIC ITP"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Fever </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Thrombocytopaenia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Microangiopathic haemolytic anaemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal impairment </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CNS changes (e.g. headache, seizure, altered mental status, coma) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Plasmapheresis = 1</span><span class=\"answer-source-red\">st</span><span class=\"answer-source-red\"> line </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Corticosteroids </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Splenectomy  </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 62 year old man with peripheral vascular disease and atrial fibrillation comes to the emergency department with an extremely painful right leg. The triage nurse gives him a category 2 on the basis\n• f pain score plus concern over distal perfusion.","parts":[{"id":"a","label":"Part A","prompt":"What are the causes of limb ischaemia? Give examples (2 marks) How do features of clinical assessment at the bedside, correlate with the Society for Vascular"},{"id":"b","label":"Part B","prompt":"Surgery (SVS) classification of lower limb ischaemia? (4 marks)"},{"id":"c","label":"Part C","prompt":"Name 2 medications, including dose / route / targets that you would prescribe in this case (4 marks)"},{"id":"d","label":"Part D","prompt":"Name 3 interventional procedures that may be used in acute limb ischaemia (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Thrombotic – atherosclerotic plaque  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Embolic – AF / CCF / AAA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Other – e.g. dissection </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Fentanyl – IV aliquots titrated to pain </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Heparin IV bolus + infusion, titrated to aPTT </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">How do features of clinical assessment at the bedside, correlate with the Society for Vascular</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Bypass </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 63 year old man presents to the ED with bilateral leg weakness following a recent diarrhoeal illness. You suspect Guillain–Barré syndrome.","parts":[{"id":"a","label":"Part A","prompt":"Describe the differences in clinical features between Guillain–Barré syndrome and spinal cord compression. Then describe the use of forced vital capacity, including threshold values, when monitoring a patient with Guillain–Barré syndrome and suspected diaphragmatic weakness. (11 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Guillain-Barre Syndrome</td><td>Spinal Cord Compression</td><td></td></tr><tr><td>History</td><td><span class=\"answer-source-red\">Prior infectious illness </span></td><td><span class=\"answer-source-red\">No prodrome </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">Others potentially ok </span></td></tr><tr><td>Exam Finding 1</td><td><span class=\"answer-source-red\">Arreflexia (LMN) </span></td><td><span class=\"answer-source-red\">Hyperreflexia (UMN) </span></td></tr><tr><td><span class=\"answer-source-red\">Sensory typically preserved </span></td><td><span class=\"answer-source-red\">Sensation impaired (level) </span></td><td></td></tr><tr><td>Exam Finding 2</td><td><span class=\"answer-source-red\">Ascending  </span></td><td><span class=\"answer-source-red\">Fixed level </span></td></tr><tr><td><span class=\"answer-source-red\">Respiratory muscle </span></td><td><span class=\"answer-source-red\">No respiratory muscle involvement </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">involvement </span></td><td><span class=\"answer-source-red\">unless above C5 </span></td><td></td></tr><tr><td>Diagnostic</td><td><span class=\"answer-source-red\">MRI not showing lesion (can </span></td><td><span class=\"answer-source-red\">MRI shows lesion </span></td></tr><tr><td>Investigation</td><td><span class=\"answer-source-red\">show enhancement of anterior </span></td><td></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">spinal nerves </span></td></tr><tr><td><span class=\"answer-source-red\">CSF showing albumin-</span></td><td><span class=\"answer-source-red\">Normal CSF </span></td><td></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">cytological dissociation (e.g. </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">high protein, low WCC) </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">EMG / nerve conduction </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">FVC not accepted answer as </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">below </span></td></tr><tr><td colspan=\"3\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 27 year old woman with no significant comorbidities presents to the emergency department with constant right upper quadrant abdominal pain for 16 hours duration. She feels hot and generally unwell and notes that she has had prior episodes of transient RUQ pain following meals but has never had any investigation.\nHer vital signs are:\n\nT 38.1\nP112\n\nBP 135/86\n\nRR 21\n\nSaO2 99% RA\nOn examination she has significant RUQ tenderness and you suspect acute cholecystitis. Your intern has some questions relating to biliary disease.","parts":[{"id":"a","label":"Part A","prompt":"Name 4 features on abdominal ultrasound that are consistent with cholecystitis (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the normal diameter of the common bile duct? (1 mark)"},{"id":"c","label":"Part C","prompt":"Name 3 causes of extrahepatic biliary obstruction (3 marks)"},{"id":"d","label":"Part D","prompt":"Name 2 complications of extrahepatic biliary obstruction (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">GB wall &gt;3mm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pericholycystic Fluid / hyperaemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sonographic murphy sign </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Gallstones </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">&lt;8mm </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Choledocholithiasis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pancreatic mass </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">cholangiocarcinoma </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Cholangitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Reduced absorption fat soluble vitamins – most importantly K </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"Your RMO is treating a patient with suspected pulmonary embolism who presented with shortness\n• f breath and light-headedness. You are discussing the classification of PE.","parts":[{"id":"a","label":"Part A","prompt":"Define (3 marks)\n• \nMassive PE\n• \nSubmassive PE\n• \nNon-massive PE"},{"id":"b","label":"Part B","prompt":"What are the 8 features of the PE rule out criteria (PERC) score? (4 marks)\nThe patient has a bilateral PE confirmed on CTPA. You review the patient and find them to be significantly dyspnoeic with the following vital signs:\n\nT 37.7\nP 134\n\nBP 83/44\n\nRR 32\n\nSaO2 87% on 10L/min"},{"id":"c","label":"Part C","prompt":"Name 3 key aspects of your management of this patient, give specifics (6 marks)\nName 2 abnormalities on bedside echocardiography when evaluating the right ventricle in this setting (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Massive PE</div><div class=\"answer-line\"><span class=\"answer-source-red\">Acute PE + haemodynamic compromise (no longer defined by size) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">BP &lt; 90 for 15min </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Improve oxygenation: HFNO2 50L/min, titrate fio2 to target SaO2 92-96% </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Vasopressors: Noradrenaline infusion target BP 90-100 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Systemic thrombolysis: Alteplase IV  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Deteriorating or arrest = 50mg alteplase bolus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Stable 100mg (10mg bolus, 90mg over 90min) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 23 year old man comes to the ED after a direct blow to the right knee complaining of significant pain. His lateral knee Xray is below.","parts":[{"id":"a","label":"Part A","prompt":"Please outline the abnormalities on this Xray (3 marks)"},{"id":"b","label":"Part B","prompt":"Name 3 indications for operative fixation for this type of injury (3 marks)"}],"propPages":["asset:img7a2b60e249bd4e99e6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Comminuted fracture of patella </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemarthrosis </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Open fracture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Extensor mechanism not intact / unable to straight leg raise </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Displaced fracture &gt;2mm </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 74 year old woman comes to the ED after suffering a significant loss of vision from her right eye. She has some perception of light, mainly at the periphery of her vision. Her main comorbidities are hypertension and type II diabetes mellitus.","parts":[{"id":"a","label":"Part A","prompt":"Name 5 causes of unilateral sudden painless vision loss (5 marks)"},{"id":"b","label":"Part B","prompt":"She undergoes fundoscopy (above). What is the diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"What is the main cause of this condition? (1 mark) What is a relative afferent pupillary defect (RAPD)? Name 2 conditions in which this will be seen (3 marks)"}],"propPages":["asset:img957cb5b80eecc22c0c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Central retinal artery occlusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Central retinal vein occlusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Vitreous haemorrhage </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Retinal detachment </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">TIA/Stroke </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Temporal arteritis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Optic neuritis </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vitreous haemorrhage</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Proliferative diabetic retinopathy </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2019.1 - ANSWERS</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"You are working in a rural hospital in North Queensland and the ambulance bring in a 19 year old man with a suspected jellyfish envenomation.\nWhat 2 jellyfish have life-threatening envenomation? (2 marks)\n1:________________________________________________________________________________","parts":[{"id":"a","label":"Part A","prompt":"Compare and contrast them in terms of their clinical features (4 marks) 1: _________________________ 2: _______________________ Timing of pain Location of pain Skin changes Cardiac arrest? He has been stung by this jellyfish What is the name of this jellyfish? (1 mark) Discuss the components of management relevant to this envenomation (4 marks)"}],"propPages":["asset:img92a5f3904262afe052"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>1: Box Jellyfish</td><td>2: Irukandji</td><td></td></tr><tr><td>Timing of pain</td><td><span class=\"answer-source-red\">Immediate </span></td><td><span class=\"answer-source-red\">Delayed 15-30min or so </span></td></tr><tr><td>Location of pain</td><td><span class=\"answer-source-red\">At site of sting </span></td><td><span class=\"answer-source-red\">Generalised / trunk </span></td></tr><tr><td>Skin changes</td><td><span class=\"answer-source-red\">Characteristic laddering lesion </span></td><td><span class=\"answer-source-red\">None </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"You receive a pre-notification that you will be receiving a 23 year old male who has been in a high- speed motor vehicle accident. He has obvious head, torso and limb injuries and is haemodynamically unstable with an unrecordable blood pressure. On arrival to your emergency department he has lost output and CPR has been commenced 2 minutes prior.","parts":[{"id":"a","label":"Part A","prompt":"What interventions will you prioritise in this setting? (5 marks)"},{"id":"b","label":"Part B","prompt":"Discuss the role of CPR in this setting (2 marks)"},{"id":"c","label":"Part C","prompt":"What is the role of ED thoracotomy in blunt traumatic cardiac arrest? (2 marks) END OF BOOKLET"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Intubation and mechanical ventilation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Bilateral finger thoracostomies </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pelvic binder application </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Reduction of long bone fractures </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Blood product administration / massive transfusion protocol </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">**Controversial area** / no evidence </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">If medical cause of arrest – has a role </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">If important procedures NOT done – likely no role / inhibits </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">If important procedures done – maybe role </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Survival poor &lt;2% </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Potential indication: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Blunt trauma + arrest &lt;10 min WITH pericardial effusion + cardiac activity on PoCUS </span></div><div class=\"answer-line\">END OF BOOKLET</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
